INSERT INTO `reviews` (`id`,`status`,`puan`,`created`,`data`) VALUES ('v1','yayinda',5,1792654181819,'{"id":"v1","ad":"Zeynep K.","rol":"Üniversite Öğrencisi \\/ Aktif Okur","baslik":"Evdeki kitaplarımı değerlendirmek için harika bir yol!","metin":"Yıllardır raflarımda okunmayı bekleyen ama yüzüne bakmadığım onlarca kitap vardı. Sitede profilimi oluşturup hepsini ekledim. Kısa sürede şehrimdeki iki öğrenciyle eşleştim; hem kitaplarım yeni sahiplerine gitti hem de \'Cömert Okur\' rozetini kazandım!","puan":5,"status":"yayinda","created":1792654181819}');
INSERT INTO `reviews` (`id`,`status`,`puan`,`created`,`data`) VALUES ('v2','yayinda',5,1793086181819,'{"id":"v2","ad":"Mert A.","rol":"Yazılım Geliştirici & Kitap Kurdu","baslik":"Aradığım ders ve roman kitaplarına bütçe sarsmadan ulaştım.","metin":"Kitap fiyatlarının bu kadar arttığı bir dönemde tür ve şehir filtresiyle aradığım kitabı yan mahallemdeki bir üyeden ödünç almak inanılmaz pratik oldu. Site içi mesajlaşma süreci de çok güvenli ilerliyor.","puan":5,"status":"yayinda","created":1793086181819}');
INSERT INTO `reviews` (`id`,`status`,`puan`,`created`,`data`) VALUES ('v3','yayinda',5,1793604581819,'{"id":"v3","ad":"Selin D.","rol":"Grafik Tasarımcı","baslik":"Raf Avcıları görevi sayesinde yeni yazarlar keşfettim.","metin":"\'Kaşif Okur\' rozeti görevi çıkana kadar hep aynı türde kitaplar okuyordum. Zorunlu ama keyifli bir takasla hiç tarzım olmayan bir macera romanı takas ettim ve bayıldım. Platform sadece kitap paylaşmıyor, okuma alışkanlıklarımızı da geliştiriyor.","puan":5,"status":"yayinda","created":1793604581819}');
