INSERT INTO `clubs` (`id`,`ad`,`il`,`kat`,`owner_id`,`created`,`data`) VALUES ('c1','Gece Okurları','İzmir','Roman / Edebiyat','u2',1792654181819,'{"id":"c1","ad":"Gece Okurları","aciklama":"Hafta sonları birlikte roman okuyup birbirimize cesaret veriyoruz. Geride kalan olursa kimse yargılamaz, herkes destek olur.","il":"İzmir","kat":"Roman \\/ Edebiyat","ownerId":"u2","members":["u2","u3","u4"],"kitap":{"ad":"Kürk Mantolu Madonna","yazar":"Sabahattin Ali","sayfa":160,"bitis":1795418981819},"hedef":40,"progress":{"u2":{"page":112,"ws":1794209381819,"wb":72},"u3":{"page":64,"ws":1794209381819,"wb":40},"u4":{"page":20,"ws":1794209381819,"wb":20}},"posts":[{"id":"p3","uid":"u3","type":"ilerleme","text":"64 sayfaya geldi (%40).","t":1794310181819,"sup":[]},{"id":"p2","uid":"u4","type":"destek","text":"Sınavlar yüzünden bu hafta çok geride kaldım. Biraz motivasyona ihtiyacım var.","t":1794274181819,"sup":["u2","u3"]},{"id":"p1","uid":"u2","type":"tartisma","text":"Raif Efendi’nin Maria’ya bakışı sizce takıntı mı, aşk mı? 5. bölümü bitirenler yazsın.","t":1794209381819,"sup":["u3"]}],"sessions":[{"id":"s1","t":1794641381819,"tur":"Çevrim içi","not":"5-8. bölümler üzerine sohbet","rsvp":["u2","u3"]}],"cheers":[{"from":"u2","to":"u4","t":1794295781819}],"created":1792654181819}');
